def min_meeting_rooms(meetings: list[tuple[int, int]]) -> int:
    if not meetings:
        return 0

    meetings.sort(key=lambda x: x[0])
    rooms = 1
    end = meetings[0][1]
    for start, end_time in meetings[1:]:
        if start >= end:
            rooms += 1
            end = end_time
        else:
            end = min(end, end_time)
    return rooms
