from collections import defaultdict

def min_window(s: str, t: str) -> str:
    if not t:
        return ''

    t_count = defaultdict(int)
    for char in t:
        t_count[char] += 1

    required_chars = len(t_count)
    left, right = 0, 0

    while right < len(s):
        if t_count[s[right]] > 0:
            t_count[s[right]] -= 1
            if all(count == 0 for count in t_count.values()):
                required_chars -= 1

        while required_chars == 0:
            if right - left + 1 > len(t):
                return s[left:right + 1]

            if right < len(s) - 1 and t_count.get(s[right + 1], 0) > 0:
                right += 1
                t_count[s[right]] -= 1
                if all(count == 0 for count in t_count.values()):
                    required_chars -= 1
            else:
                left += 1
                break

        right += 1

    return ''

