def evaluate(expr: str) -> int:
    def apply_operator(ops, values):
        result = values[0]
        for op, value in zip(ops, values[1:]):
            if op == '+':
                result += value
            elif op == '-':
                result -= value
            elif op == '*':
                result *= value
            elif op == '/':
                result //= value
        return result

    def tokenize(expr):
        tokens = []
        current = ''
        for char in expr:
            if char.isspace():
                if current:
                    tokens.append(int(current) if current.isdigit() else current)
                    current = ''
            elif char in '+-*/()':
                if current:
                    tokens.append(int(current) if current.isdigit() else current)
                    current = ''
                tokens.append(char)
            else:
                current += char
        if current:
            tokens.append(int(current) if current.isdigit() else current)
        return tokens

    def parse(tokens):
        if len(tokens) == 1:
            return int(tokens[0])
        if tokens[0] == '(':
            return parse(tokens[1:]) + (1,)
        if tokens[0] in '+-*/':
            return apply_operator(tokens[0], parse(tokens[1:]))
        return int(tokens[0])

    return parse(tokenize(expr))
