def parse_duration(s: str) -> int:
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total_seconds = 0
    parts = s.split()
    for part in parts:
        value = ''
        for char in part:
            if char.isdigit():
                value += char
            elif char in units:
                if value:
                    total_seconds += int(value) * units[char]
                    value = ''
                else:
                    raise ValueError("Malformed duration string")
        if value:
            raise ValueError("Malformed duration string")
    return total_seconds

