def binary_search(nums: list[int], target: int) -> int:
    low, high = 0, len(nums) - 1
    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            left, right = mid, mid
            while left > 0 and nums[left-1] == target:
                left -= 1
            while right < len(nums) - 1 and nums[right+1] == target:
                right += 1
            return left
        elif nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1
