def evaluate(expr: str) -> int:
    def apply_op(op, num1, num2):
        if op == '+':
            return num1 + num2
        elif op == '-':
            return num1 - num2
        elif op == '*':
            return num1 * num2
        else:
            return num1 // num2

    def tokenize(expr):
        tokens = []
        num = ''
        for char in expr:
            if char.isspace():
                if num:
                    tokens.append(int(num))
                    num = ''
            elif char in '+-*/()':
                if num:
                    tokens.append(int(num))
                    num = ''
                tokens.append(char)
            else:
                num += char
        if num:
            tokens.append(int(num))
        return tokens

    def parse(tokens):
        def parse_expr(tokens):
            if len(tokens) == 0:
                return 0
            if tokens[0] in '+-*/':
                return apply_op(tokens.pop(0), parse_expr(tokens), parse_expr(tokens))
            if len(tokens) == 0 or tokens[0] in '+-*/':
                return parse_expr(tokens)
            return int(tokens.pop(0))

        return parse_expr(tokens)

    return parse(tokenize(expr))
