def sliding_max(nums: list[int], k: int) -> list[int]:
    from collections import deque
    max_deque = deque()
    result = []

    for i in range(k):
        while max_deque and nums[i] >= nums[max_deque[-1]]:
            max_deque.pop()
        max_deque.append(i)

    for i in range(k, len(nums)):
        result.append(nums[max_deque[0]])

        if max_deque[0] == i - k:
            max_deque.popleft()

        while max_deque and nums[i] >= nums[max_deque[-1]]:
            max_deque.pop()
        max_deque.append(i)

    result.append(nums[max_deque[0]])

