        if row == n:
            ways[0] += 1
            return
        for col in range(n):
            if is_valid(board, row, col):
                board[row] = col
                place_queens(n, row + 1, board, ways)

    ways = [0]
    place_queens(n, 0, [-1] * n, ways)
    return ways[0]

