def evaluate(expr: str) -> int:
    def apply_operator(ops, op):
        res = ops[0]
        for op in ops[1:]:
            if op == '+':
                res += ops[1]
            elif op == '-':
                res -= ops[1]
            elif op == '*':
                res *= ops[1]
            elif op == '/':
                res //= ops[1]
        return res

    def parse_and_evaluate(expression):
        ops = []
        i = 0
        while i < len(expression):
            if expression[i].isdigit():
                j = i
                while j < len(expression) and expression[j].isdigit():
                    j += 1
                ops.append(int(expression[i:j]))
                i = j
            elif expression[i] in '+-*/() ':
                if expression[i] in '+-':
                    ops.append(int(ops.pop()))
                elif expression[i] in '*/':
                    ops.append(apply_operator(ops, expression[i]))
                elif expression[i] == '(':
                    ops.append('(')
                elif expression[i] == ')':
                    while ops[-1] != '(':
                        ops.append(apply_operator(ops, ops.pop()))
                    ops.pop()
                i += 1
            else:
                raise ValueError("Invalid expression")

        return apply_operator(ops, '+')

    return parse_and_evaluate(expr)

