def lru_misses(capacity: int, requests: list[int]) -> int:
    cache = {}
    most_recently_used = None
    misses = 0
    for request in requests:
        if request in cache:
            most_recently_used = request
            for key, value in cache.items():
                if key == request:
                    cache.pop(key)
                    break
        else:
            if len(cache) >= capacity:
                cache.pop(next(key for key in cache))
                misses += 1
            cache[request] = None
            most_recently_used = request
    return misses
```

