def n_queens(n: int) -> int:
    def is_valid(board, row, col):
        for i in range(row):
            if board[i] == col or \
               board[i] - i == col - row or \
               board[i] + i == col + row:
                return False
        return True

    def place_queens(board, row):
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if is_valid(board, row, col):
                board[row] = col
                count += place_queens(board, row + 1)
        return count

    board = [-1] * n
    return place_queens(board, 0)

