def evaluate(expr: str) -> int:
    def apply_operator(ops, values):
        result = values[0]
        for op, value in zip(ops, values[1:]):
            if op == '+':
                result += value
            elif op == '-':
                result -= value
            elif op == '*':
                result *= value
            elif op == '/':
                result //= value
        return result

    def parse_expression(expr):
        values = []
        ops = []
        for token in expr.split():
            if token in '+-*/':
                while ops and ops[-1] in '+-*/':
                    values.append(int(apply_operator(ops, values)))
                    ops.pop()
                ops.append(token)
            elif token == '(':
                ops.append(token)
            elif token == ')':
                while ops[-1] != '(':
                    values.append(int(apply_operator(ops, values)))
                    ops.pop()
                ops.pop()
            else:
                values.append(int(token))
        while ops:
            values.append(int(apply_operator(ops, values)))
        return values[0]

    return parse_expression(expr)

